// Planet 1: Cookie Nebula. Web, headers and authentication.
QB.push(

/* ---------- 2023 ---------- */
{id:"H23-1", t:1, s:"e23", kind:"single",
 q:["Når en HTTP-vert svarer med <code>HTTP/1.1 302 Found</code>, hvilken HTTP-header trengs i responsen?",
    "When an HTTP host answers with <code>HTTP/1.1 302 Found</code>, which HTTP header does the response need?"],
 o:[["<code>Referer</code>","<code>Referer</code>"],
    ["<code>Location</code>","<code>Location</code>"],
    ["<code>Content-Type</code>","<code>Content-Type</code>"],
    ["<code>Set-Cookie</code>","<code>Set-Cookie</code>"]],
 a:1,
 w:["302 er en omdirigering (3xx). Nettleseren må vite <i>hvor</i> den skal gå, og det står i <code>Location: /ny/sti</code>. Uten <code>Location</code> er 302-svaret meningsløst.<br>Typisk etter innlogging: <code>302 Found</code> + <code>Location: /dashboard</code> + <code>Set-Cookie: sid=…</code>, men bare <code>Location</code> er påkrevd.",
    "302 is a redirect (3xx). The browser must know <i>where</i> to go, and that is given in <code>Location: /new/path</code>. Without <code>Location</code> a 302 is meaningless.<br>Typical after login: <code>302 Found</code> + <code>Location: /dashboard</code> + <code>Set-Cookie: sid=…</code>, but only <code>Location</code> is required."],
 x:[["<code>Referer</code> er en <i>forespørsels</i>header som klienten sender (siden den kom fra), ikke en responsheader.","<code>Referer</code> is a <i>request</i> header sent by the client (the page it came from), not a response header."],
    null,
    ["<code>Content-Type</code> beskriver en eventuell body. Et 302-svar trenger ingen body.","<code>Content-Type</code> describes a body, if any. A 302 response needs no body."],
    ["<code>Set-Cookie</code> følger ofte med en redirect etter innlogging, men den er valgfri.","<code>Set-Cookie</code> often comes with a redirect after login, but it is optional."]]},

{id:"H23-3", t:1, s:"e23", kind:"single",
 q:["Under en sikkerhetstest finner du et endepunkt som svarer med feilmeldingen under etter at du sendte fuzzing-payloaden <code>http://translation.no/translate/nb/nn/hei\"</code>. Hva er den mest sannsynlige feilen du nettopp har oppdaget?",
    "During a security test you find an endpoint that answers with the error below after you sent the fuzzing payload <code>http://translation.no/translate/nb/nn/hei\"</code>. What is the most likely flaw you have just discovered?"],
 c:"sh: 1: Syntax error: Unterminated quoted string",
 o:[["Insecure deserialisation","Insecure deserialisation"],
    ["Server-side template injection","Server-side template injection"],
    ["SQL injection","SQL injection"],
    ["Command injection","Command injection"]],
 a:3,
 w:["Meldingen kommer fra <code>sh</code>, altså et skall. Serveren bygger trolig kommandolinjen <code>translate nb nn \"INPUT\"</code> og kjører den med <code>sh</code>, og vårt ekstra <code>\"</code> gjør at anførselstegnene ikke er balansert.<br>Neste steg (PoC): <code>hei\";id;\"</code> eller <code>hei$(id)</code>.<br>Fiks: ikke bruk skall. Send argumentene som en liste (<code>execFile</code>, <code>subprocess.run([...])</code>) og valider input mot en hviteliste.",
    "The message comes from <code>sh</code>, i.e. a shell. The server probably builds the command line <code>translate nb nn \"INPUT\"</code> and runs it with <code>sh</code>, and our extra <code>\"</code> leaves the quotes unbalanced.<br>Next step (PoC): <code>hei\";id;\"</code> or <code>hei$(id)</code>.<br>Fix: don't use a shell. Pass the arguments as a list (<code>execFile</code>, <code>subprocess.run([...])</code>) and validate input against an allowlist."],
 x:[["Deserialisering gir typisk feil fra pickle/Java/PHP-unserialize, ikke fra <code>sh</code>.","Deserialisation errors typically come from pickle/Java/PHP unserialize, not from <code>sh</code>."],
    ["SSTI testes med <code>{{7*7}}</code> og gir malmotor-feil (Jinja2, Twig), ikke en skallfeil.","SSTI is tested with <code>{{7*7}}</code> and gives template-engine errors (Jinja2, Twig), not a shell error."],
    ["En SQL-feil ville nevnt databasen, f.eks. <i>unterminated quoted string at or near</i> fra PostgreSQL eller <i>You have an error in your SQL syntax</i>. Her er det <code>sh</code> som klager.","An SQL error would mention the database, e.g. <i>unterminated quoted string at or near</i> from PostgreSQL or <i>You have an error in your SQL syntax</i>. Here it is <code>sh</code> that complains."],
    null]},

{id:"H23-5a", t:1, s:"e23", kind:"single",
 q:["(Oppgave 5: koble beste input til angrepsvektor.) Hvilken input er best for å finne <b>SQL injection</b>?",
    "(Task 5: match the best input to the attack vector.) Which input is best for finding <b>SQL injection</b>?"],
 o:[["<code>|| id</code>","<code>|| id</code>"],
    ["<code>' or sleep(10); --</code>","<code>' or sleep(10); --</code>"],
    ["<code>{{ 2+2 }}</code>","<code>{{ 2+2 }}</code>"],
    ["<code>%p</code>","<code>%p</code>"]],
 a:1,
 w:["<code>'</code> lukker strengen i SQL-spørringen, <code>or sleep(10)</code> legger til en betingelse som får databasen til å vente 10 s, og <code>--</code> kommenterer ut resten. Svarer serveren 10 s senere, har du en (blind, tidsbasert) SQL-injeksjon selv om ingenting vises i svaret.<br>Fiks: parameteriserte spørringer (<code>?</code>, <code>$1</code>).",
    "<code>'</code> closes the string in the SQL query, <code>or sleep(10)</code> adds a condition that makes the database wait 10 s, and <code>--</code> comments out the rest. If the server answers 10 s later you have (blind, time-based) SQL injection even though nothing shows in the response.<br>Fix: parameterised queries (<code>?</code>, <code>$1</code>)."],
 x:[["<code>|| id</code> er en skall-payload: kommandoinjeksjon.","<code>|| id</code> is a shell payload: command injection."],
    null,
    ["<code>{{ 2+2 }}</code> tester server-side template injection (svar 4).","<code>{{ 2+2 }}</code> tests server-side template injection (answer 4)."],
    ["<code>%p</code> tester format string-sårbarhet i C (<code>printf(buf)</code>).","<code>%p</code> tests a format-string bug in C (<code>printf(buf)</code>)."]]},

{id:"H23-5b", t:1, s:"e23", kind:"single",
 q:["(Oppgave 5.) Hvilken input er best for å finne <b>command injection</b>?",
    "(Task 5.) Which input is best for finding <b>command injection</b>?"],
 o:[["<code>\"&gt;</code>","<code>\"&gt;</code>"],
    ["<code>http://0.0.0.0:8081</code>","<code>http://0.0.0.0:8081</code>"],
    ["<code>' or sleep(10); --</code>","<code>' or sleep(10); --</code>"],
    ["<code>|| id</code>","<code>|| id</code>"]],
 a:3,
 w:["<code>||</code> betyr «kjør neste kommando hvis den forrige feilet» i skallet. Hvis input havner i <code>sh -c \"ping \" + input</code>, kjører <code>id</code> og svaret viser <code>uid=33(www-data) …</code>.<br>Andre varianter: <code>; id</code>, <code>&amp;&amp; id</code>, <code>$(id)</code>, <code>`id`</code>.<br>Fiks: ingen skall, argumentliste, hviteliste.",
    "<code>||</code> means “run the next command if the previous one failed” in the shell. If the input ends up in <code>sh -c \"ping \" + input</code>, <code>id</code> runs and the response shows <code>uid=33(www-data) …</code>.<br>Other variants: <code>; id</code>, <code>&amp;&amp; id</code>, <code>$(id)</code>, <code>`id`</code>.<br>Fix: no shell, argument list, allowlist."],
 x:[["<code>\"&gt;</code> bryter ut av et HTML-attributt: XSS.","<code>\"&gt;</code> breaks out of an HTML attribute: XSS."],
    ["En intern URL tester SSRF: får serveren til å hente noe internt.","An internal URL tests SSRF: making the server fetch something internal."],
    ["Det er en SQL-payload, ikke en skall-payload.","That is an SQL payload, not a shell payload."],
    null]},

{id:"H23-5c", t:1, s:"e23", kind:"single",
 q:["(Oppgave 5.) Hvilken input er best for å finne <b>server-side template injection</b>?",
    "(Task 5.) Which input is best for finding <b>server-side template injection</b>?"],
 o:[["<code>{{ 2+2 }}</code>","<code>{{ 2+2 }}</code>"],
    ["<code>\"&gt;</code>","<code>\"&gt;</code>"],
    ["<code>%p</code>","<code>%p</code>"],
    ["<code>|| id</code>","<code>|| id</code>"]],
 a:0,
 w:["Hvis brukerinput blir en del av <i>selve malen</i> (f.eks. <code>render_template_string(\"Hei \" + navn)</code> i Jinja2), evaluerer malmotoren <code>{{ 2+2 }}</code> og siden viser <b>4</b>. Da kan angriperen ofte gå videre til kodekjøring via objekter i malkonteksten.<br>Fiks: send input som en variabel til en fast mal (<code>render_template(\"hei.html\", navn=navn)</code>).",
    "If user input becomes part of <i>the template itself</i> (e.g. <code>render_template_string(\"Hi \" + name)</code> in Jinja2), the engine evaluates <code>{{ 2+2 }}</code> and the page shows <b>4</b>. The attacker can then often reach code execution through objects in the template context.<br>Fix: pass input as a variable to a fixed template (<code>render_template(\"hi.html\", name=name)</code>)."],
 x:[null,
    ["<code>\"&gt;</code> er en XSS-test i nettleseren, ikke en test av malmotoren på serveren.","<code>\"&gt;</code> is an XSS test in the browser, not a test of the server's template engine."],
    ["<code>%p</code> er for C-format string (lekker stakkverdier).","<code>%p</code> is for C format strings (leaks stack values)."],
    ["<code>|| id</code> er kommandoinjeksjon i skallet.","<code>|| id</code> is command injection in the shell."]]},

{id:"H23-5d", t:1, s:"e23", kind:"single",
 q:["(Oppgave 5.) Hvilken input er best for å finne <b>cross-site scripting (XSS)</b>?",
    "(Task 5.) Which input is best for finding <b>cross-site scripting (XSS)</b>?"],
 o:[["<code>{{ 2+2 }}</code>","<code>{{ 2+2 }}</code>"],
    ["<code>' or sleep(10); --</code>","<code>' or sleep(10); --</code>"],
    ["<code>\"&gt;</code>","<code>\"&gt;</code>"],
    ["<code>http://0.0.0.0:8081</code>","<code>http://0.0.0.0:8081</code>"]],
 a:2,
 w:["Hvis input reflekteres uescapet i et attributt, f.eks. <code>&lt;input value=\"INPUT\"&gt;</code>, lukker <code>\"&gt;</code> både attributtet og taggen. Ser du <code>\"&gt;</code> rått i HTML-kilden, kan du fortsette med <code>\"&gt;&lt;img src=x onerror=alert(1)&gt;</code>.<br>Fiks: kontekstriktig output-escaping (<code>&amp;lt;</code>, <code>&amp;quot;</code>), og CSP som ekstra forsvar.",
    "If input is reflected unescaped in an attribute, e.g. <code>&lt;input value=\"INPUT\"&gt;</code>, <code>\"&gt;</code> closes both the attribute and the tag. If you see <code>\"&gt;</code> raw in the HTML source, continue with <code>\"&gt;&lt;img src=x onerror=alert(1)&gt;</code>.<br>Fix: context-aware output escaping (<code>&amp;lt;</code>, <code>&amp;quot;</code>), with CSP as defence in depth."],
 x:[["<code>{{ 2+2 }}</code> tester SSTI på serveren.","<code>{{ 2+2 }}</code> tests SSTI on the server."],
    ["Det er en tidsbasert SQL-injeksjon.","That is time-based SQL injection."],
    null,
    ["En intern adresse tester SSRF.","An internal address tests SSRF."]]},

{id:"H23-5e", t:1, s:"e23", kind:"single",
 q:["(Oppgave 5.) Hvilken input er best for å finne <b>server-side request forgery (SSRF)</b>?",
    "(Task 5.) Which input is best for finding <b>server-side request forgery (SSRF)</b>?"],
 o:[["<code>%p</code>","<code>%p</code>"],
    ["<code>http://0.0.0.0:8081</code>","<code>http://0.0.0.0:8081</code>"],
    ["<code>\"&gt;</code>","<code>\"&gt;</code>"],
    ["<code>' or sleep(10); --</code>","<code>' or sleep(10); --</code>"]],
 a:1,
 w:["SSRF: et endepunkt som henter en URL for deg (bildeforhåndsvisning, webhook, «importer fra URL»). Gir du det <code>http://0.0.0.0:8081</code> eller <code>http://127.0.0.1:8080</code>, ber du serveren kontakte <i>seg selv</i> på en intern port som ikke er åpen utad. Skyens metadata-tjeneste <code>http://169.254.169.254/</code> er det klassiske målet.<br>Fiks: hviteliste over tillatte verter, blokker interne adresser etter DNS-oppslag.",
    "SSRF: an endpoint that fetches a URL for you (image preview, webhook, “import from URL”). Giving it <code>http://0.0.0.0:8081</code> or <code>http://127.0.0.1:8080</code> asks the server to contact <i>itself</i> on an internal port that is not exposed. The cloud metadata service <code>http://169.254.169.254/</code> is the classic target.<br>Fix: allowlist of hosts, block internal addresses after DNS resolution."],
 x:[["<code>%p</code> er format string i C.","<code>%p</code> is a C format string."],
    null,
    ["<code>\"&gt;</code> er XSS.","<code>\"&gt;</code> is XSS."],
    ["Det er SQL-injeksjon.","That is SQL injection."]]},

{id:"H23-5f", t:1, s:"e23", kind:"single",
 q:["(Oppgave 5.) Hvilken input er best for å finne en <b>format string-sårbarhet</b>?",
    "(Task 5.) Which input is best for finding a <b>format string vulnerability</b>?"],
 o:[["<code>|| id</code>","<code>|| id</code>"],
    ["<code>{{ 2+2 }}</code>","<code>{{ 2+2 }}</code>"],
    ["<code>http://0.0.0.0:8081</code>","<code>http://0.0.0.0:8081</code>"],
    ["<code>%p</code>","<code>%p</code>"]],
 a:3,
 w:["I C er <code>printf(buf)</code> med brukerstyrt <code>buf</code> en format string-feil. <code>%p</code> ber printf skrive ut neste «argument» som peker, selv om ingen ble sendt, så du lekker registre og stakkverdier (f.eks. <code>0x7ffd…</code>). Det brukes til å lekke canary og adresser (ASLR/PIE-bypass). <code>%n</code> kan skrive til minnet.<br>Fiks: <code>printf(\"%s\", buf)</code>.",
    "In C, <code>printf(buf)</code> with user-controlled <code>buf</code> is a format-string bug. <code>%p</code> asks printf to print the next “argument” as a pointer although none was passed, so you leak registers and stack values (e.g. <code>0x7ffd…</code>). It is used to leak the canary and addresses (ASLR/PIE bypass). <code>%n</code> can write to memory.<br>Fix: <code>printf(\"%s\", buf)</code>."],
 x:[["<code>|| id</code> er kommandoinjeksjon.","<code>|| id</code> is command injection."],
    ["<code>{{ 2+2 }}</code> er SSTI. Klammeparenteser betyr ingenting for printf.","<code>{{ 2+2 }}</code> is SSTI. Braces mean nothing to printf."],
    ["Det er SSRF.","That is SSRF."],
    null]},

/* ---------- 2024 ---------- */
{id:"H24-1", t:1, s:"e24", kind:"single",
 q:["Hvilken av følgende er IKKE en vanlig fase i en penetrasjonstestmetodikk?",
    "Which of the following is NOT a common phase in a penetration-testing methodology?"],
 o:[["Reconnaissance","Reconnaissance"],
    ["Reporting","Reporting"],
    ["Social engineering","Social engineering"],
    ["Exploitation","Exploitation"]],
 a:2,
 w:["Vanlige faser: (1) planlegging og avgrensning (scope, avtale), (2) <b>reconnaissance</b>/informasjonsinnhenting, (3) skanning og sårbarhetsanalyse (nmap, fuzzing), (4) <b>exploitation</b>, (5) post-exploitation (eskalering, persistens), (6) <b>reporting</b> med funn, alvorlighet og anbefalt fiks.<br>Social engineering er en <i>teknikk</i> (phishing, telefon) som kan brukes i recon eller exploitation hvis den er i scope, ikke en egen fase.",
    "Common phases: (1) planning and scoping (rules of engagement), (2) <b>reconnaissance</b>/information gathering, (3) scanning and vulnerability analysis (nmap, fuzzing), (4) <b>exploitation</b>, (5) post-exploitation (escalation, persistence), (6) <b>reporting</b> with findings, severity and recommended fixes.<br>Social engineering is a <i>technique</i> (phishing, phone calls) that may be used in recon or exploitation if it is in scope, not a phase of its own."],
 x:[["Recon (innhenting av informasjon om målet) er første tekniske fase i alle metodikker.","Recon (gathering information about the target) is the first technical phase in every methodology."],
    ["Rapporten er selve leveransen fra en pentest. Uten den er testen verdiløs for kunden.","The report is the actual deliverable of a pentest. Without it the test is worthless to the client."],
    null,
    ["Exploitation, å faktisk utnytte sårbarheter, er kjernefasen.","Exploitation, actually using the vulnerabilities, is the core phase."]]},

{id:"H24-3", t:1, s:"e24", kind:"single",
 q:["Hvilket av følgende er et vanlig verktøy som brukes til portskanning?",
    "Which of the following is a common tool used for port scanning?"],
 o:[["Metasploit","Metasploit"],
    ["Wireshark","Wireshark"],
    ["nmap","nmap"],
    ["Burp Suite","Burp Suite"]],
 a:2,
 w:["<b>nmap</b> sender prober til en rekke porter og klassifiserer dem som <i>open</i>, <i>closed</i> eller <i>filtered</i>. Eksempler: <code>nmap -sV host</code> (tjenesteversjoner), <code>nmap -p- host</code> (alle 65535 TCP-porter), <code>nmap -sS</code> (SYN-skann).",
    "<b>nmap</b> sends probes to a range of ports and classifies them as <i>open</i>, <i>closed</i> or <i>filtered</i>. Examples: <code>nmap -sV host</code> (service versions), <code>nmap -p- host</code> (all 65535 TCP ports), <code>nmap -sS</code> (SYN scan)."],
 x:[["Metasploit er et rammeverk for <i>exploitation</i> (ferdige exploits og payloads), ikke primært en portskanner.","Metasploit is an <i>exploitation</i> framework (ready-made exploits and payloads), not primarily a port scanner."],
    ["Wireshark fanger og analyserer nettverkstrafikk passivt. Den skanner ikke.","Wireshark captures and analyses network traffic passively. It does not scan."],
    null,
    ["Burp Suite er en HTTP-proxy for å fange opp og endre webforespørsler.","Burp Suite is an HTTP proxy for intercepting and modifying web requests."]]},

{id:"H24-4", t:1, s:"e24", kind:"single",
 q:["Hva er formålet med et bug bounty-program?",
    "What is the purpose of a bug bounty programme?"],
 o:[["Å gi opplæring til sikkerhetspersonell.","To train security staff."],
    ["Å fikse feil i programvare.","To fix bugs in software."],
    ["Å selge exploits til høyeste budgiver.","To sell exploits to the highest bidder."],
    ["Å belønne sikkerhetsforskere for å finne sårbarheter.","To reward security researchers for finding vulnerabilities."]],
 a:3,
 w:["Et bug bounty-program (f.eks. via HackerOne/Bugcrowd) gir eksterne forskere lov til å teste innenfor et definert <i>scope</i> og betaler en dusør for gyldige, ansvarlig rapporterte sårbarheter. Det er en form for koordinert avsløring (responsible disclosure).",
    "A bug bounty programme (e.g. via HackerOne/Bugcrowd) lets outside researchers test within a defined <i>scope</i> and pays a reward for valid, responsibly reported vulnerabilities. It is a form of coordinated (responsible) disclosure."],
 x:[["Opplæring er ikke målet. Programmet kjøper funn fra eksterne.","Training is not the goal. The programme buys findings from outsiders."],
    ["Forskerne <i>finner og rapporterer</i>. Det er leverandøren som fikser feilene.","The researchers <i>find and report</i>. The vendor fixes the bugs."],
    ["Det er exploit-megling på gråmarkedet, det motsatte av ansvarlig avsløring.","That is grey-market exploit brokering, the opposite of responsible disclosure."],
    null]},

{id:"H24-5", t:1, s:"e24", kind:"single",
 q:["Hvilken av følgende er IKKE en vanlig sikkerhetsheader som brukes for å beskytte mot webapplikasjonsangrep?",
    "Which of the following is NOT a common security header used to protect against web-application attacks?"],
 o:[["<code>X-Content-Type-Options</code>","<code>X-Content-Type-Options</code>"],
    ["<code>X-XSS-Protection</code>","<code>X-XSS-Protection</code>"],
    ["<code>X-Powered-By</code>","<code>X-Powered-By</code>"],
    ["<code>X-Frame-Options</code>","<code>X-Frame-Options</code>"]],
 a:2,
 w:["<code>X-Powered-By: Express</code> (eller <code>PHP/7.4.3</code>) forteller bare hvilken teknologi serveren bruker. Den beskytter ingenting, og den <i>lekker</i> informasjon som hjelper angriperen å finne kjente sårbarheter. Fjern den (<code>app.disable('x-powered-by')</code>). Det samme gjelder en detaljert <code>Server</code>-header.",
    "<code>X-Powered-By: Express</code> (or <code>PHP/7.4.3</code>) just tells which technology the server uses. It protects nothing, and it <i>leaks</i> information that helps an attacker find known vulnerabilities. Remove it (<code>app.disable('x-powered-by')</code>). The same goes for a detailed <code>Server</code> header."],
 x:[["<code>X-Content-Type-Options: nosniff</code> hindrer MIME-sniffing (f.eks. at en opplastet .txt tolkes som script).","<code>X-Content-Type-Options: nosniff</code> stops MIME sniffing (e.g. an uploaded .txt being run as script)."],
    ["<code>X-XSS-Protection</code> slo på nettleserens gamle XSS-filter. Den er utdatert (erstattet av CSP), men den <i>var</i> en sikkerhetsheader.","<code>X-XSS-Protection</code> turned on the browser's old XSS filter. It is deprecated (replaced by CSP), but it <i>was</i> a security header."],
    null,
    ["<code>X-Frame-Options: DENY</code> hindrer at siden lastes i en iframe: beskytter mot clickjacking.","<code>X-Frame-Options: DENY</code> stops the page being loaded in an iframe: protects against clickjacking."]]},

{id:"H24-6a", t:1, s:"e24", kind:"single",
 q:["Oppgave 6.1: Du skal fuzze <code>https://api.example.com/api/v2/users/&lt;userid&gt;</code> med alle tegn 0x00–0xFF, URL-kodet med <code>printf</code>. Hvilken løkke gjør dette riktig?",
    "Task 6.1: You must fuzz <code>https://api.example.com/api/v2/users/&lt;userid&gt;</code> with every character 0x00–0xFF, URL-encoded with <code>printf</code>. Which loop does it correctly?"],
 o:[["<code>for i in $(seq 0 255); do x=$(printf \"%02x\" $i); curl -s -o /dev/null -w \"%{http_code} %{size_download}\\n\" \"https://api.example.com/api/v2/users/$x\"; done</code>",
     "<code>for i in $(seq 0 255); do x=$(printf \"%02x\" $i); curl -s -o /dev/null -w \"%{http_code} %{size_download}\\n\" \"https://api.example.com/api/v2/users/$x\"; done</code>"],
    ["<code>for i in $(seq 0 255); do x=$(printf \"%%%02x\" $i); echo -n \"$x \"; curl -s -o /dev/null -w \"%{http_code} %{size_download}\\n\" \"https://api.example.com/api/v2/users/$x\"; done</code>",
     "<code>for i in $(seq 0 255); do x=$(printf \"%%%02x\" $i); echo -n \"$x \"; curl -s -o /dev/null -w \"%{http_code} %{size_download}\\n\" \"https://api.example.com/api/v2/users/$x\"; done</code>"],
    ["<code>for i in $(seq 1 256); do x=$(printf \"%%%02x\" $i); echo -n \"$x \"; curl -s -o /dev/null -w \"%{http_code} %{size_download}\\n\" \"https://api.example.com/api/v2/users/$x\"; done</code>",
     "<code>for i in $(seq 1 256); do x=$(printf \"%%%02x\" $i); echo -n \"$x \"; curl -s -o /dev/null -w \"%{http_code} %{size_download}\\n\" \"https://api.example.com/api/v2/users/$x\"; done</code>"],
    ["<code>for i in $(seq 0 255); do x=$(printf \"%%%02x\" $i); echo -n \"$x \"; curl -s -o /dev/null -w \"%{http_code} %{size_download}\\n\" 'https://api.example.com/api/v2/users/$x'; done</code>",
     "<code>for i in $(seq 0 255); do x=$(printf \"%%%02x\" $i); echo -n \"$x \"; curl -s -o /dev/null -w \"%{http_code} %{size_download}\\n\" 'https://api.example.com/api/v2/users/$x'; done</code>"]],
 a:1,
 w:["Delene:<br>• <code>seq 0 255</code>: alle 256 bytes.<br>• <code>printf \"%%%02x\" $i</code>: <code>%%</code> gir en bokstavelig <code>%</code>, <code>%02x</code> gir to hex-sifre, så 47 → <code>%2f</code>. Serveren URL-dekoder det til selve byten.<br>• <code>echo -n \"$x \"</code>: skriver hvilken byte linjen gjelder.<br>• <code>curl -s</code> (stille), <code>-o /dev/null</code> (kast body), <code>-w '%{http_code} %{size_download}\\n'</code> (skriv statuskode og antall bytes).<br>• URL-en i <b>doble</b> anførselstegn slik at <code>$x</code> utvides.",
    "The parts:<br>• <code>seq 0 255</code>: all 256 bytes.<br>• <code>printf \"%%%02x\" $i</code>: <code>%%</code> gives a literal <code>%</code>, <code>%02x</code> gives two hex digits, so 47 → <code>%2f</code>. The server URL-decodes it to the byte itself.<br>• <code>echo -n \"$x \"</code>: prints which byte the line is for.<br>• <code>curl -s</code> (silent), <code>-o /dev/null</code> (discard body), <code>-w '%{http_code} %{size_download}\\n'</code> (print status code and byte count).<br>• The URL in <b>double</b> quotes so <code>$x</code> expands."],
 x:[["<code>%02x</code> uten <code>%%</code> gir <code>2f</code>, ikke <code>%2f</code>. Du sender da strengen «2f» som bruker-ID, aldri selve byten. Linjene mangler også hvilken byte de gjelder.","<code>%02x</code> without <code>%%</code> gives <code>2f</code>, not <code>%2f</code>. You then send the string “2f” as the user id, never the byte itself. The lines also don't say which byte they belong to."],
    null,
    ["Off-by-one: <code>seq 1 256</code> hopper over 0x00 (nullbyten, ofte den mest interessante) og ender med <code>%100</code>, som ikke er én byte.","Off-by-one: <code>seq 1 256</code> skips 0x00 (the null byte, often the most interesting) and ends with <code>%100</code>, which is not a single byte."],
    ["Enkle anførselstegn utvider ikke variabler: alle 256 forespørsler går til den bokstavelige stien <code>/users/$x</code>.","Single quotes do not expand variables: all 256 requests go to the literal path <code>/users/$x</code>."]]},

{id:"H24-6b", t:1, s:"e24", kind:"tf",
 q:["Oppgave 6: I Bash skriver <code>printf \"%%%02x\" 46</code> ut <code>%2e</code>, URL-kodingen av tegnet <code>.</code>.",
    "Task 6: In Bash, <code>printf \"%%%02x\" 46</code> prints <code>%2e</code>, the URL encoding of the character <code>.</code>."],
 o:[["Sant","True"],["Usant","False"]],
 a:0,
 w:["46 = 2·16 + 14 = 0x2e, og 0x2e er ASCII <code>.</code>. Formatet <code>%%</code> skriver <code>%</code>, og <code>%02x</code> skriver tallet som to små hex-sifre med ledende null. Andre nyttige: 0 → <code>%00</code>, 10 → <code>%0a</code> (linjeskift), 39 → <code>%27</code> (<code>'</code>), 47 → <code>%2f</code> (<code>/</code>), 65 → <code>%41</code> (<code>A</code>), 255 → <code>%ff</code>.",
    "46 = 2·16 + 14 = 0x2e, and 0x2e is ASCII <code>.</code>. The format <code>%%</code> prints <code>%</code>, and <code>%02x</code> prints the number as two lower-case hex digits with a leading zero. Other useful ones: 0 → <code>%00</code>, 10 → <code>%0a</code> (newline), 39 → <code>%27</code> (<code>'</code>), 47 → <code>%2f</code> (<code>/</code>), 65 → <code>%41</code> (<code>A</code>), 255 → <code>%ff</code>."],
 x:[null,
    ["Det stemmer: 46 = 0x2e = <code>.</code>, og <code>%%</code> gir prosenttegnet foran.","It is true: 46 = 0x2e = <code>.</code>, and <code>%%</code> gives the percent sign in front."]]},

{id:"H24-6c", t:1, s:"e24", kind:"single",
 q:["Oppgave 6.2: Et utdrag av utdataen fra fuzz-løkken står under (byte, statuskode, størrelse i bytes). Hvilken linje tyder mest på <b>SQL-injeksjon</b>?",
    "Task 6.2: An excerpt of the fuzz loop's output is shown below (byte, status code, size in bytes). Which line most suggests <b>SQL injection</b>?"],
 c:"%00 400 0\n%01 404 22\n...\n%26 404 22\n%27 500 1873\n%28 404 22\n...\n%2e 200 48211\n%2f 404 22\n...\n%41 404 22\n%42 404 22\n...",
 o:[["<code>%00 400 0</code>","<code>%00 400 0</code>"],
    ["<code>%27 500 1873</code>","<code>%27 500 1873</code>"],
    ["<code>%2e 200 48211</code>","<code>%2e 200 48211</code>"],
    ["<code>%41 404 22</code>","<code>%41 404 22</code>"]],
 a:1,
 w:["Grunnlinjen er <code>404 22</code> (ukjent bruker). Se etter avvik i statuskode <i>og</i> størrelse.<br><code>%27</code> er <code>'</code>. Ett enkelt anførselstegn gir <code>500 Internal Server Error</code> med en stor body (1873 bytes, sannsynligvis en stack trace eller SQL-feilmelding). Det betyr at <code>'</code> brøt spørringen: klassisk tegn på SQL-injeksjon. Neste steg: hent body-en (uten <code>-o /dev/null</code>) og prøv <code>' OR 1=1 --</code> eller <code>' or sleep(10); --</code>.",
    "The baseline is <code>404 22</code> (unknown user). Look for deviations in status code <i>and</i> size.<br><code>%27</code> is <code>'</code>. A single quote gives <code>500 Internal Server Error</code> with a large body (1873 bytes, probably a stack trace or SQL error message). That means <code>'</code> broke the query: the classic sign of SQL injection. Next step: fetch the body (without <code>-o /dev/null</code>) and try <code>' OR 1=1 --</code> or <code>' or sleep(10); --</code>."],
 x:[["En nullbyte avvist med <code>400 Bad Request</code> og tom body er normal, korrekt inputvalidering.","A null byte rejected with <code>400 Bad Request</code> and an empty body is normal, correct input validation."],
    null,
    ["Interessant, men et annet funn: <code>/users/.</code> normaliseres til <code>/users/</code> og returnerer 48 kB, trolig hele brukerlisten. Det er informasjonslekkasje/manglende tilgangskontroll, ikke SQLi.","Interesting, but a different finding: <code>/users/.</code> is normalised to <code>/users/</code> and returns 48 kB, probably the whole user list. That is information disclosure/missing access control, not SQLi."],
    ["Dette er grunnlinjen: samme svar som nesten alle andre bytes.","This is the baseline: the same response as almost every other byte."]]},

{id:"H24-6d", t:1, s:"e24", kind:"multi",
 q:["Oppgave 6.2: Hvilke utsagn om hvordan du leser og bruker utdataen fra fuzz-løkken er riktige?",
    "Task 6.2: Which statements about reading and using the fuzz loop's output are correct?"],
 o:[["Finn grunnlinjen (den vanligste kombinasjonen av status og størrelse) og filtrer den bort, f.eks. med <code>grep -v \" 404 22$\"</code>.","Find the baseline (the most common status/size pair) and filter it out, e.g. with <code>grep -v \" 404 22$\"</code>."],
    ["Hvis statuskoden er lik for alle bytes, kan størrelseskolonnen ignoreres.","If the status code is the same for every byte, the size column can be ignored."],
    ["Et <code>500</code>-svar for én bestemt byte bør følges opp manuelt med målrettede payloads for den klassen av sårbarhet.","A <code>500</code> response for one particular byte should be followed up manually with targeted payloads for that vulnerability class."],
    ["En byte som gir <code>200</code> med uvanlig stor body bør hentes i sin helhet for å se om den lekker data.","A byte that gives <code>200</code> with an unusually large body should be fetched in full to see whether it leaks data."],
    ["Et <code>500</code>-svar viser at serveren avviste angrepet, så endepunktet er trygt.","A <code>500</code> response shows that the server rejected the attack, so the endpoint is safe."]],
 a:[0,2,3],
 w:["Fremgangsmåte: (1) finn det «normale» svaret, (2) se etter avvik i statuskode (<code>500</code> = uhåndtert feil, <code>200</code>/<code>403</code> = annen kodesti) <i>og</i> størrelse (samme status, annen lengde = annen behandling), eventuelt responstid, (3) følg opp hver avvikende byte manuelt: hent hele svaret, gjett hvilken kodesti det trigget (SQL, filsti, skall, parser) og bygg en målrettet PoC.",
    "Method: (1) find the “normal” response, (2) look for deviations in status code (<code>500</code> = unhandled error, <code>200</code>/<code>403</code> = different code path) <i>and</i> size (same status, different length = different handling), and possibly response time, (3) follow up each deviating byte by hand: fetch the full response, guess which code path it triggered (SQL, file path, shell, parser) and build a targeted PoC."],
 x:[["Riktig: grunnlinjen er støy. Å fjerne den gjør de få interessante linjene synlige.","Correct: the baseline is noise. Removing it makes the few interesting lines visible."],
    ["Feil: <code>200 1500</code> mot <code>200 48211</code> er to helt ulike svar. Størrelsen er ofte det eneste tegnet.","Wrong: <code>200 1500</code> vs <code>200 48211</code> are two very different responses. Size is often the only sign."],
    ["Riktig: 500 betyr at input nådde kode som krasjet. Bruk tegnet til å velge payloads (f.eks. <code>'</code> → SQLi, <code>;</code> → skall).","Correct: 500 means the input reached code that crashed. Use the byte to choose payloads (e.g. <code>'</code> → SQLi, <code>;</code> → shell)."],
    ["Riktig: en stor body der man forventet 404 kan være en liste over andre brukeres data (informasjonslekkasje/IDOR).","Correct: a large body where a 404 was expected can be a list of other users' data (information disclosure/IDOR)."],
    ["Feil: 500 betyr at serveren <i>ikke</i> håndterte input og krasjet. Det er et funn, ikke et forsvar.","Wrong: 500 means the server did <i>not</i> handle the input and crashed. It is a finding, not a defence."]]},

{id:"H24-9a", t:1, s:"e24", kind:"multi",
 q:["Oppgave 9: Hvilke er de tre autentiseringsfaktorene?",
    "Task 9: Which are the three authentication factors?"],
 o:[["Noe en <b>vet</b> (passord, PIN)","Something you <b>know</b> (password, PIN)"],
    ["Noe en <b>har</b> (telefon, sikkerhetsnøkkel)","Something you <b>have</b> (phone, security key)"],
    ["Noe en <b>vil</b> (ønsket brukernavn)","Something you <b>want</b> (desired username)"],
    ["Noe en <b>er</b> (fingeravtrykk, ansikt)","Something you <b>are</b> (fingerprint, face)"],
    ["Noe en <b>bruker</b> (nettleser, IP-adresse)","Something you <b>use</b> (browser, IP address)"]],
 a:[0,1,3],
 w:["Kunnskap (vet), besittelse (har) og iboende egenskap/biometri (er). Tofaktor (2FA/MFA) betyr minst <b>to ulike</b> faktorer, f.eks. passord + TOTP-kode fra appen på telefonen.",
    "Knowledge (know), possession (have) and inherence/biometrics (are). Two-factor (2FA/MFA) means at least <b>two different</b> factors, e.g. password + a TOTP code from the app on your phone."],
 x:[["Riktig: kunnskapsfaktoren.","Correct: the knowledge factor."],
    ["Riktig: besittelsesfaktoren. En TOTP-kode beviser at du har telefonen med den hemmelige nøkkelen.","Correct: the possession factor. A TOTP code proves you have the phone holding the secret key."],
    ["Feil: et ønsket brukernavn er en identifikator, ikke et bevis.","Wrong: a desired username is an identifier, not proof."],
    ["Riktig: den iboende (biometriske) faktoren.","Correct: the inherence (biometric) factor."],
    ["Feil: nettleser og IP er kontekstsignaler for risikovurdering, ikke en av de tre faktorene.","Wrong: browser and IP are context signals for risk scoring, not one of the three factors."]]},

{id:"H24-9b", t:1, s:"e24", kind:"tf",
 q:["Innlogging med passord og deretter et sikkerhetsspørsmål («Hva het ditt første kjæledyr?») er tofaktorautentisering.",
    "Logging in with a password followed by a security question (“What was your first pet's name?”) is two-factor authentication."],
 o:[["Sant","True"],["Usant","False"]],
 a:1,
 w:["Begge er <b>noe en vet</b>, altså samme faktor to ganger. Det er totrinns, men ikke tofaktor. En angriper som har phishet eller lekket kunnskapen din, har begge. Ekte 2FA kombinerer ulike faktorer: passord + TOTP-app/sikkerhetsnøkkel (har) eller + fingeravtrykk (er).",
    "Both are <b>something you know</b>, i.e. the same factor twice. It is two-step, but not two-factor. An attacker who has phished or leaked your knowledge has both. Real 2FA combines different factors: password + TOTP app/security key (have) or + fingerprint (are)."],
 x:[["Feil: to hemmeligheter av samme type gir ikke en ny faktor.","Wrong: two secrets of the same type do not add a new factor."],
    null]},

{id:"H24-10a", t:1, s:"e24", kind:"multi",
 q:["Oppgave 10: Du implementerer en autentiseringsløsning fra bunnen av (se bort fra 2FA). Hvilke deler bør være på plass?",
    "Task 10: You implement an authentication solution from scratch (ignore 2FA). Which parts should be in place?"],
 o:[["Passord lagret med salt og en treg hash (Argon2id, bcrypt, scrypt)","Passwords stored with a salt and a slow hash (Argon2id, bcrypt, scrypt)"],
    ["Rate limiting eller midlertidig låsing etter mange feilede forsøk","Rate limiting or temporary lockout after many failed attempts"],
    ["Ulike feilmeldinger for «ukjent bruker» og «feil passord» så brukeren vet hva som var galt","Different error messages for “unknown user” and “wrong password” so the user knows what went wrong"],
    ["Tilfeldig sesjons-ID i en cookie med <code>HttpOnly</code>, <code>Secure</code>, <code>SameSite</code>, ny ID ved innlogging og utløp/utlogging","A random session id in a cookie with <code>HttpOnly</code>, <code>Secure</code>, <code>SameSite</code>, a new id at login, and expiry/logout"],
    ["Alt over HTTPS, også innloggingsskjemaet","Everything over HTTPS, including the login form"],
    ["Sesjons-ID-en sendes som URL-parameter så den virker uten cookies","The session id is sent as a URL parameter so it works without cookies"]],
 a:[0,1,3,4],
 w:["Sjekkliste for oppgave 10:<br>• <b>Lagring</b>: salt + treg hash, aldri klartekst eller kryptering.<br>• <b>Transport</b>: HTTPS + HSTS.<br>• <b>Brute force</b>: rate limiting, lockout/CAPTCHA.<br>• <b>Sesjon</b>: tilfeldig ID med høy entropi, cookie-flagg, regenerer ved innlogging (mot session fixation), utløp, ugyldiggjør ved utlogging.<br>• <b>Ingen brukeropplisting</b>: samme melding og responstid uansett.<br>• Sikker tilbakestilling av passord (engangs-token med kort levetid), passordpolicy, logging.",
    "Checklist for task 10:<br>• <b>Storage</b>: salt + slow hash, never plaintext or encryption.<br>• <b>Transport</b>: HTTPS + HSTS.<br>• <b>Brute force</b>: rate limiting, lockout/CAPTCHA.<br>• <b>Session</b>: random high-entropy id, cookie flags, regenerate at login (against session fixation), expiry, invalidate on logout.<br>• <b>No user enumeration</b>: same message and response time either way.<br>• Secure password reset (single-use, short-lived token), password policy, logging."],
 x:[["Riktig: gjør en lekket database dyr å knekke.","Correct: makes a leaked database expensive to crack."],
    ["Riktig: stopper online gjetting og credential stuffing.","Correct: stops online guessing and credential stuffing."],
    ["Feil: det gir <i>brukeropplisting</i> (user enumeration). Angriperen lærer hvilke brukernavn som finnes. Bruk «Feil brukernavn eller passord».","Wrong: that enables <i>user enumeration</i>. The attacker learns which usernames exist. Use “Wrong username or password”."],
    ["Riktig: sesjonshåndtering er halve autentiseringen. Etter innlogging er cookien like mye verdt som passordet.","Correct: session handling is half of authentication. After login the cookie is worth as much as the password."],
    ["Riktig: uten TLS kan passord og sesjons-cookie avlyttes.","Correct: without TLS the password and session cookie can be sniffed."],
    ["Feil: ID-en i URL-en lekker via <code>Referer</code>, logger og nettleserhistorikk, og gjør session fixation lett.","Wrong: an id in the URL leaks through <code>Referer</code>, logs and browser history, and makes session fixation easy."]]},

{id:"H24-10b", t:1, s:"e24", kind:"single",
 q:["Oppgave 10: Hvordan bør passord lagres i databasen?",
    "Task 10: How should passwords be stored in the database?"],
 o:[["<code>SHA-256(salt ‖ passord)</code> med unikt salt per bruker","<code>SHA-256(salt ‖ password)</code> with a unique salt per user"],
    ["Kryptert med AES-256-GCM med en nøkkel som ligger på serveren","Encrypted with AES-256-GCM under a key kept on the server"],
    ["Argon2id (eller bcrypt/scrypt) med unikt tilfeldig salt per bruker","Argon2id (or bcrypt/scrypt) with a unique random salt per user"],
    ["<code>MD5(passord)</code>, siden hashen ikke kan reverseres","<code>MD5(password)</code>, since the hash cannot be reversed"]],
 a:2,
 w:["Passordhashing skal være <b>treg</b> (og minnekrevende for Argon2id/scrypt) og <b>saltet</b>. Saltet gjør at like passord gir ulik hash og ødelegger regnbuetabeller. Tregheten (justerbar kostnadsparameter) gjør at en GPU bare klarer tusener i stedet for milliarder gjetninger per sekund. Ved innlogging: hent salt og parametere, hash forsøket på nytt og sammenlign i konstant tid.",
    "Password hashing must be <b>slow</b> (and memory-hard for Argon2id/scrypt) and <b>salted</b>. The salt makes equal passwords hash differently and defeats rainbow tables. The slowness (a tunable cost parameter) means a GPU manages thousands instead of billions of guesses per second. At login: fetch the salt and parameters, hash the attempt again and compare in constant time."],
 x:[["Saltet hjelper, men SHA-256 er laget for å være <i>rask</i>: en GPU tester milliarder passord per sekund mot en lekket hash.","The salt helps, but SHA-256 is designed to be <i>fast</i>: a GPU tests billions of passwords per second against a leaked hash."],
    ["Kryptering er reversibel. Den som får tak i nøkkelen (ofte på samme server som databasen) får alle passordene i klartekst.","Encryption is reversible. Whoever gets the key (often on the same server as the database) gets every password in plaintext."],
    null,
    ["MD5 er rask og ødelagt, og uten salt slås vanlige passord opp direkte i regnbuetabeller.","MD5 is fast and broken, and without a salt common passwords are looked up directly in rainbow tables."]]},

{id:"H24-10c", t:1, s:"e24", kind:"single",
 q:["Oppgave 10 (sesjoner): En app beholder samme sesjons-ID før og etter innlogging. En angriper får offeret til å bruke en sesjons-ID angriperen kjenner. Hva heter angrepet, og hva er fiksen?",
    "Task 10 (sessions): An app keeps the same session id before and after login. An attacker gets the victim to use a session id the attacker knows. What is the attack called, and what is the fix?"],
 o:[["CSRF, fikses med <code>SameSite=Strict</code>","CSRF, fixed with <code>SameSite=Strict</code>"],
    ["Session fixation, fikses ved å lage en ny sesjons-ID ved innlogging","Session fixation, fixed by issuing a new session id at login"],
    ["Session hijacking via XSS, fikses med <code>HttpOnly</code>","Session hijacking via XSS, fixed with <code>HttpOnly</code>"],
    ["Brute force av sesjons-ID, fikses med lengre ID","Session-id brute force, fixed with a longer id"]],
 a:1,
 w:["<b>Session fixation</b>: angriperen henter en gyldig, uinnlogget sesjons-ID og planter den hos offeret (lenke med <code>?sid=…</code> eller en cookie satt via et subdomene). Offeret logger inn, og hvis serveren gjenbruker ID-en, er angriperens ID nå innlogget som offeret.<br>Fiks: regenerer ID ved innlogging (og ved rettighetsendring), godta bare server-genererte ID-er, aldri ID i URL-en.",
    "<b>Session fixation</b>: the attacker obtains a valid, logged-out session id and plants it on the victim (a link with <code>?sid=…</code> or a cookie set via a subdomain). The victim logs in, and if the server reuses the id, the attacker's id is now logged in as the victim.<br>Fix: regenerate the id at login (and on privilege change), accept only server-generated ids, never put the id in the URL."],
 x:[["CSRF får offerets nettleser til å sende en forespørsel med offerets cookie. Angriperen kjenner ikke sesjons-ID-en.","CSRF makes the victim's browser send a request with the victim's cookie. The attacker never knows the session id."],
    null,
    ["Her <i>stjeles</i> ikke ID-en, angriperen <i>bestemte</i> den på forhånd. <code>HttpOnly</code> hjelper ikke.","Here the id is not <i>stolen</i>, the attacker <i>chose</i> it in advance. <code>HttpOnly</code> does not help."],
    ["Angriperen trenger ikke gjette. Han kjenner allerede ID-en, så lengden er irrelevant.","The attacker need not guess. He already knows the id, so its length is irrelevant."]]},

/* ---------- new ---------- */
{id:"n1-01", t:1, s:"new", kind:"multi",
 q:["Serveren setter cookien under. Hvilke utsagn er riktige?",
    "The server sets the cookie below. Which statements are correct?"],
 c:"Set-Cookie: sid=9f8c2e7a41d0; Path=/; HttpOnly; Secure; SameSite=Lax",
 o:[["JavaScript på siden kan ikke lese cookien med <code>document.cookie</code>, så XSS kan ikke stjele den direkte.","JavaScript on the page cannot read the cookie with <code>document.cookie</code>, so XSS cannot steal it directly."],
    ["Cookien sendes bare over HTTPS.","The cookie is only sent over HTTPS."],
    ["Cookien er kryptert, så verdien kan ikke ses i nettleserens utviklerverktøy.","The cookie is encrypted, so its value cannot be seen in the browser's developer tools."],
    ["Cookien sendes ikke med i POST-forespørsler som starter på et annet nettsted, noe som demper CSRF.","The cookie is not sent with POST requests started from another site, which mitigates CSRF."],
    ["<code>HttpOnly</code> gjør XSS umulig.","<code>HttpOnly</code> makes XSS impossible."]],
 a:[0,1,3],
 w:["<code>HttpOnly</code>: skjult for JavaScript. <code>Secure</code>: bare over HTTPS. <code>SameSite</code>: <code>Strict</code> = aldri på forespørsler fra andre nettsteder, <code>Lax</code> = bare ved toppnivå-navigering med GET (lenkeklikk), <code>None</code> = alltid (krever <code>Secure</code>).<br>Ingen av flaggene krypterer verdien eller fjerner selve XSS-feilen.",
    "<code>HttpOnly</code>: hidden from JavaScript. <code>Secure</code>: HTTPS only. <code>SameSite</code>: <code>Strict</code> = never on requests from other sites, <code>Lax</code> = only on top-level GET navigation (clicking a link), <code>None</code> = always (requires <code>Secure</code>).<br>None of the flags encrypt the value or remove the XSS bug itself."],
 x:[["Riktig: det er nettopp hva <code>HttpOnly</code> gjør.","Correct: that is exactly what <code>HttpOnly</code> does."],
    ["Riktig: <code>Secure</code> hindrer at cookien lekker over vanlig HTTP.","Correct: <code>Secure</code> stops the cookie leaking over plain HTTP."],
    ["Feil: ingen flagg krypterer. Verdien er synlig i devtools og i klartekst i forespørselen (beskyttet av TLS på veien).","Wrong: no flag encrypts. The value is visible in devtools and in plaintext in the request (protected by TLS in transit)."],
    ["Riktig: med <code>Lax</code> sendes den bare ved toppnivå-navigering med GET fra andre nettsteder, ikke ved cross-site POST.","Correct: with <code>Lax</code> it is only sent on top-level GET navigation from other sites, not on cross-site POST."],
    ["Feil: XSS kan fortsatt gjøre forespørsler som brukeren og lese siden. <code>HttpOnly</code> beskytter bare selve cookie-verdien.","Wrong: XSS can still make requests as the user and read the page. <code>HttpOnly</code> only protects the cookie value itself."]]},

{id:"n1-02", t:1, s:"new", kind:"single",
 q:["En forespørsel til <code>https://bank.example/api/me</code> med <code>Origin: https://evil.example</code> gir svaret under. Hva er problemet?",
    "A request to <code>https://bank.example/api/me</code> with <code>Origin: https://evil.example</code> gets the response below. What is the problem?"],
 c:"HTTP/1.1 200 OK\nContent-Type: application/json\nAccess-Control-Allow-Origin: https://evil.example\nAccess-Control-Allow-Credentials: true\n\n{\"user\":\"alice\",\"iban\":\"NO93 8601 1117 947\"}",
 o:[["Ingenting: CORS-headere beskytter serveren mot forespørsler fra andre nettsteder.","Nothing: CORS headers protect the server from requests by other sites."],
    ["<code>Content-Type</code> burde vært <code>text/plain</code> for å hindre CORS.","<code>Content-Type</code> should have been <code>text/plain</code> to prevent CORS."],
    ["Serveren speiler en vilkårlig <code>Origin</code> og tillater credentials, så evil.example kan lese den innloggede brukerens data.","The server reflects any <code>Origin</code> and allows credentials, so evil.example can read the logged-in user's data."],
    ["Problemet er at <code>Access-Control-Allow-Origin</code> ikke er <code>*</code>.","The problem is that <code>Access-Control-Allow-Origin</code> is not <code>*</code>."]],
 a:2,
 w:["Same-Origin Policy hindrer at et script på evil.example <i>leser</i> svar fra bank.example. CORS er et unntak serveren gir. Her svarer serveren «ja» til hvilken som helst <code>Origin</code> og sier at cookies er med (<code>Allow-Credentials: true</code>). Da kan <code>fetch(url, {credentials:\"include\"})</code> fra evil.example lese offerets kontodata.<br>Fiks: en hviteliste over tillatte opphav, og aldri speil <code>Origin</code> ukritisk.",
    "The Same-Origin Policy stops a script on evil.example from <i>reading</i> responses from bank.example. CORS is an exception the server grants. Here the server says “yes” to any <code>Origin</code> and says cookies are included (<code>Allow-Credentials: true</code>). So <code>fetch(url, {credentials:\"include\"})</code> from evil.example can read the victim's account data.<br>Fix: an allowlist of permitted origins, and never reflect <code>Origin</code> blindly."],
 x:[["CORS beskytter ikke serveren. Den <i>løsner</i> nettleserens Same-Origin Policy, og her løsner den den for alle.","CORS does not protect the server. It <i>relaxes</i> the browser's Same-Origin Policy, and here it relaxes it for everyone."],
    ["Content-Type har ingenting å si for om nettleseren lar evil.example lese svaret.","Content-Type has no bearing on whether the browser lets evil.example read the response."],
    null,
    ["<code>*</code> kan ikke kombineres med credentials: nettleseren nekter da å gi svaret til scriptet. Speiling er verre enn <code>*</code>.","<code>*</code> cannot be combined with credentials: the browser then refuses to hand the response to the script. Reflection is worse than <code>*</code>."]]},

{id:"n1-03", t:1, s:"new", kind:"single",
 q:["Du kjører nmap mot et mål i scope og får utdataen under. Hvilket utsagn er riktig?",
    "You run nmap against an in-scope target and get the output below. Which statement is correct?"],
 c:"$ nmap -sV 10.0.0.5\nPORT     STATE    SERVICE VERSION\n22/tcp   open     ssh     OpenSSH 8.9p1 Ubuntu\n80/tcp   open     http    nginx 1.18.0\n443/tcp  closed   https\n3306/tcp filtered mysql",
 o:[["<code>closed</code> på 443 betyr at en brannmur blokkerer porten.","<code>closed</code> on 443 means a firewall blocks the port."],
    ["Skannet dekket alle 65535 TCP-porter.","The scan covered all 65535 TCP ports."],
    ["<code>-sV</code> betyr at nmap utnyttet tjenestene for å finne versjonene.","<code>-sV</code> means nmap exploited the services to find the versions."],
    ["<code>filtered</code> på 3306 betyr at probene ble droppet, så nmap kan ikke si om MySQL lytter.","<code>filtered</code> on 3306 means the probes were dropped, so nmap cannot tell whether MySQL is listening."]],
 a:3,
 w:["nmap-tilstander: <b>open</b> = en tjeneste svarte. <b>closed</b> = verten svarte (TCP RST), men ingenting lytter. <b>filtered</b> = ingen svar eller ICMP-avvisning, typisk en brannmur, så status er ukjent.<br>Uten <code>-p</code> skanner nmap de 1000 vanligste portene. <code>-p-</code> gir alle 65535. <code>-sV</code> gjør versjonsdeteksjon ved å snakke med tjenesten (bannere). Versjonene (OpenSSH 8.9p1, nginx 1.18.0) brukes videre til å slå opp kjente CVE-er.",
    "nmap states: <b>open</b> = a service answered. <b>closed</b> = the host answered (TCP RST) but nothing is listening. <b>filtered</b> = no reply or an ICMP rejection, typically a firewall, so the state is unknown.<br>Without <code>-p</code> nmap scans the 1000 most common ports. <code>-p-</code> gives all 65535. <code>-sV</code> does version detection by talking to the service (banners). The versions (OpenSSH 8.9p1, nginx 1.18.0) are then used to look up known CVEs."],
 x:[["Feil: <code>closed</code> betyr at verten aktivt svarte med RST. Den er nåbar, men ingen tjeneste lytter. Brannmur gir <code>filtered</code>.","Wrong: <code>closed</code> means the host actively answered with RST. It is reachable but no service listens. A firewall gives <code>filtered</code>."],
    ["Feil: uten <code>-p-</code> skanner nmap bare de 1000 vanligste portene.","Wrong: without <code>-p-</code> nmap only scans the 1000 most common ports."],
    ["Feil: <code>-sV</code> er versjonsdeteksjon via bannere og prober, ikke exploitation.","Wrong: <code>-sV</code> is version detection via banners and probes, not exploitation."],
    null]},

{id:"n1-04", t:1, s:"new", kind:"tf",
 q:["Saltet i passordhashing må holdes hemmelig. Hvis det lagres i klartekst ved siden av hashen, gir det ingen beskyttelse.",
    "The salt in password hashing must be kept secret. If it is stored in plaintext next to the hash, it gives no protection."],
 o:[["Sant","True"],["Usant","False"]],
 a:1,
 w:["Saltet er <b>ikke</b> hemmelig. bcrypt og Argon2id lagrer det rett i hash-strengen (f.eks. <code>$argon2id$v=19$m=65536,t=3,p=4$&lt;salt&gt;$&lt;hash&gt;</code>). Det virker fordi det er <b>unikt</b>: like passord gir ulike hasher, forhåndsberegnede regnbuetabeller er ubrukelige, og angriperen må knekke hver bruker for seg. En hemmelig verdi i tillegg (lagret utenfor databasen) kalles en <i>pepper</i>.",
    "The salt is <b>not</b> secret. bcrypt and Argon2id store it right in the hash string (e.g. <code>$argon2id$v=19$m=65536,t=3,p=4$&lt;salt&gt;$&lt;hash&gt;</code>). It works because it is <b>unique</b>: equal passwords give different hashes, precomputed rainbow tables are useless, and the attacker must crack each user separately. An extra secret value (kept outside the database) is called a <i>pepper</i>."],
 x:[["Feil: saltets effekt kommer fra at det er unikt per bruker, ikke fra at det er hemmelig.","Wrong: the salt's effect comes from being unique per user, not from being secret."],
    null]}

);
